package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.CountActiveLoansPort;
import com.example.lending.application.port.out.LoadActiveLoansPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, CountActiveLoansPort, LoadLoanPort, LoadActiveLoansPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }

    @Override
    public long countActiveLoans(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findWithLockById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public List<ActiveLoanRow> loadActiveLoans(UUID memberId, int page, int size) {
        return loanJpaRepository.findActiveLoans(memberId, PageRequest.of(page, size)).stream()
                .map(p -> new ActiveLoanRow(p.getLoanId(), p.getBookId(), p.getTitle(), p.getLoanedAt(), p.getDueAt()))
                .toList();
    }
}
package com.example.lending.adapter.out.persistence;

import jakarta.persistence.LockModeType;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    // 반납되지 않은 대출만 센다
    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    // 반납되지 않은 대출만 가져온다. 대출일이 같으면 id 순으로 정렬해 페이지가 흔들리지 않게 한다
    @Query("select l.id as loanId, l.bookId as bookId, b.title as title, l.loanedAt as loanedAt, l.dueAt as dueAt "
            + "from LoanJpaEntity l, BookJpaEntity b "
            + "where b.id = l.bookId and l.memberId = :memberId and l.returnedAt is null "
            + "order by l.loanedAt, l.id")
    List<ActiveLoanProjection> findActiveLoans(@Param("memberId") UUID memberId, Pageable pageable);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    Optional<LoanJpaEntity> findWithLockById(UUID id);
}
