void book_search_matches_part_of_title_ignoring_case() throws Exception {
    registerBook("Lendsearch Spring in Action");
    registerBook("lendSEARCH Guide");
    registerBook("Lendsearch 관련 없는 책은 아님 spring");
    registerBook("Other book");

    mockMvc.perform(get("/books").param("title", "LENDSEARCH"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.length()").value(3))
            .andExpect(jsonPath("$[*].title", containsInAnyOrder(
                    "Lendsearch Spring in Action", "lendSEARCH Guide", "Lendsearch 관련 없는 책은 아님 spring")))
            .andExpect(jsonPath("$[0].status").value("AVAILABLE"));
}

@Test
void book_search_without_match_returns_empty_list() throws Exception {
    registerBook("검색 결과 없음 책");

    mockMvc.perform(get("/books").param("title", "존재하지않는제목0x9"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.length()").value(0));
}

@Test
void book_search_treats_wildcards_as_plain_text() throws Exception {
    registerBook("wildcard 100% 실전");
    registerBook("wildcard plain");

    mockMvc.perform(get("/books").param("title", "%"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.length()").value(1))
            .andExpect(jsonPath("$[0].title").value("wildcard 100% 실전"));
